    "factor_updates": [
      {
        "factor": "Petition filed to challenge Lamag result",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A petition increases the chance of an overturn, but Malaysia’s overturn rate remains historically low."
      },
      {
        "factor": "Lamag victory margin (BN by 5,681 votes)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "A large margin lowers the likelihood that miscounts or irregularities could overturn the result."
      },
      {
        "factor": "No overturn reported by May 1, 2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Public reporting through May 1 shows no reversal, reducing the short-term risk."
      },
      {
        "factor": "Historical base-rate of election-petitions overturning results in Malaysia",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Overturns are rare, providing a downward pressure on the probability."
      },
      {
        "factor": "Evidentiary threshold for overturning (proof of irregularities)",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Even with a petition, the court requires strong evidence; threshold remains high."
      }
    ],
    "synthesis_rationale": "Starting from a modest anchor in the low single-digit percent range, the large Lamag margin, absence of a reported petition overturn by the deadline, and the historical rarity of overturns collectively pull the posterior down toward 2%. The combination of factors is weighted toward low risk, but the presence of a petition pathway and Sabah’s petition history keeps the possibility non-zero. Calibration acknowledges potential late developments but assigns a small probability to reversal within the May 1, 2026 window."
  }
}

